exercises.solution:
public class Temps {
    public static double cToF(double c) {
        return Math.round((c * 9 / 5 + 32) * 10) / 10.0;
    }

    public static double fToC(double f) {
        return Math.round((f - 32) * 5 / 9 * 10) / 10.0;
    }
}

public class Price {
    public static double total(int qty, double unitPrice) {
        return total(qty, unitPrice, 0);
    }

    public static double total(int qty, double unitPrice, double discountPercent) {
        return Math.round(qty * unitPrice * (100 - discountPercent)) / 100.0;
    }
}

public class Line {
    public static String clean(String name) {
        String s = name.trim();
        return s.isEmpty() ? "" : s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
    }

    public static String fmtKg(double kg) {
        return String.format("%.1f kg", kg);
    }

    public static String line(String name, double kg) {
        return clean(name) + ": " + fmtKg(kg);
    }
}
